mapper.sql:
SELECT l.id AS ledger_id,l.ledger_no,l.business_no,r.order_id,r.receipt_no,r.business_no AS receipt_business_no,l.refund_no,l.amount,l.currency,r.confirmed_at,
  CASE WHEN r.disposition='NORMAL' THEN 'NORMAL_RECEIPT' ELSE 'ABNORMAL_RECEIPT' END AS kind
FROM tc_payment_receipt r
JOIN tc_money_ledger l ON l.tenant_id=r.tenant_id AND l.receipt_id=r.id AND l.entry_type='RECEIPT'
WHERE r.tenant_id=#{tenant} AND r.currency=#{currency} AND l.currency=#{currency}
  AND r.confirmed_at >= #{q.createdFrom} AND r.confirmed_at < #{q.createdTo}
AND l.id > #{q.after}
UNION ALL
SELECT l.id,l.ledger_no,l.business_no,r.order_id,r.receipt_no,r.business_no AS receipt_business_no,l.refund_no,l.amount,l.currency,h.confirmed_at,
  CASE WHEN r.disposition='NORMAL' THEN 'NORMAL_REFUND' ELSE 'ABNORMAL_REFUND' END
FROM tc_payment_refund_hold h
JOIN tc_money_ledger l ON l.tenant_id=h.tenant_id AND l.receipt_id=h.receipt_id AND l.refund_no=h.refund_no AND l.entry_type='REFUND'
JOIN tc_payment_receipt r ON r.tenant_id=h.tenant_id AND r.id=h.receipt_id
WHERE h.tenant_id=#{tenant} AND h.currency=#{currency} AND l.currency=#{currency} AND h.state='SUCCEEDED'
  AND h.confirmed_at >= #{q.createdFrom} AND h.confirmed_at < #{q.createdTo}
AND l.id > #{q.after}

mapper.select:
WITH funds AS ()
SELECT f.ledger_id,f.ledger_no,f.business_no,o.order_no,f.receipt_no,f.refund_no,
       o.business_no AS order_business_no,f.receipt_business_no,r.business_no AS refund_business_no,
       f.kind,f.amount,f.currency,f.confirmed_at
FROM funds f
JOIN tc_order o ON o.tenant_id=#{tenant} AND o.id=f.order_id
LEFT JOIN tc_refund r ON r.tenant_id=o.tenant_id AND r.order_id=o.id AND r.refund_no=f.refund_no

  WHERE f.kind IN ('NORMAL_RECEIPT','NORMAL_REFUND')
  WHERE f.kind=#{q.filters.scope}

AND

    f.business_no=#{q.filters.ledgerNo}
    f.ledger_no=#{q.filters.ledgerNo}


ORDER BY f.ledger_id LIMIT #{q.fetchLimit}
